// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.base;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;

/**
 * Browsers load module scripts only with a JavaScript content type, and servlet containers such as Tomcat do not map
 * {@code .mjs} by default, so the Workbench web application must declare that mapping itself.
 */
class WorkbenchModuleScriptTypeTest {

	@Test
	void webApplicationServesItsModuleScriptsAsJavaScript() throws Exception {
		List<Path> moduleScripts;
		try (Stream<Path> files = Files.walk(Path.of("src/main/webapp/scripts"))) {
			moduleScripts = files.filter(file -> file.getFileName().toString().endsWith(".mjs")).toList();
		}
		assertThat(moduleScripts).as("the Workbench ships module scripts").isNotEmpty();

		String webXml = Files.readString(Path.of("src/main/webapp/WEB-INF/web.xml"), StandardCharsets.UTF_8);

		assertThat(webXml).containsPattern("(?s)<mime-mapping>\\s*<extension>mjs</extension>\\s*"
				+ "<mime-type>text/javascript</mime-type>\\s*</mime-mapping>");
	}
}
